//! Actual WVC precision/shape diagnostic only; no serving selection.
#[path="../lt.rs"]mod lt;
use cudarc::{driver::{CudaDevice,DevicePtr,LaunchAsync,LaunchConfig,sys},cublas::{result as br,sys as bs}};use serde::Deserialize;use serde_json::json;use sha2::{Digest,Sha256};use std::{fs,path::PathBuf};
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn serial(v:&[f32])->Vec<u8>{v.iter().flat_map(|x|x.to_le_bytes()).collect()}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Identity{path:PathBuf,bytes:usize,sha256:String}impl Identity{fn read(&self)->Result<Vec<u8>,String>{let b=fs::read(&self.path).map_err(|e|e.to_string())?;if b.len()!=self.bytes||hash(&b)!=self.sha256{return Err("identity mismatch".into())}Ok(b)}}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Plan{profile:bool,gpu_uuid:String,source_reference_gpu_uuid:String,provenance:Identity,native_ptx:Identity,weights:Identity,full_attention:Identity,decode_attention:Identity,expected_prefill:Identity,expected_decode:Identity,heads:usize,rank:usize,values:usize,tokens:Vec<usize>}
fn floats(b:&[u8])->Result<Vec<f32>,String>{if b.len()%4!=0{return Err("F32 extent".into())}let v:Vec<_>=b.chunks_exact(4).map(|b|f32::from_le_bytes(b.try_into().unwrap())).collect();if v.iter().any(|v|!v.is_finite()){return Err("nonfinite".into())}Ok(v)}fn shorts(b:&[u8])->Result<Vec<u16>,String>{if b.len()%2!=0{return Err("BF16 extent".into())}Ok(b.chunks_exact(2).map(|v|u16::from_le_bytes(v.try_into().unwrap())).collect())}fn widen(v:u16)->f32{f32::from_bits((v as u32)<<16)}fn round(v:f32)->u16{let b=v.to_bits();((b.wrapping_add(0x7fff+((b>>16)&1)))>>16)as u16}fn bserial(v:&[u16])->Vec<u8>{v.iter().flat_map(|v|v.to_le_bytes()).collect()}
struct Blas(bs::cublasHandle_t);impl Drop for Blas{fn drop(&mut self){unsafe{let _=br::destroy_handle(self.0);}}}
fn run(plan:&str,out:&str)->Result<(),String>{let p:Plan=serde_json::from_slice(&fs::read(plan).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let proof:serde_json::Value=serde_json::from_slice(&p.provenance.read()?).map_err(|e|e.to_string())?;if proof["collectionPassed"]!=true||p.heads==0||p.rank==0||p.values==0||p.tokens.first()!=Some(&1){return Err("admission".into())}let w=shorts(&p.weights.read()?)?;let f=floats(&p.full_attention.read()?)?;let e=floats(&p.decode_attention.read()?)?;let expected=[shorts(&p.expected_prefill.read()?)?,shorts(&p.expected_decode.read()?)?];if w.len()!=p.heads.checked_mul(p.rank).and_then(|n|n.checked_mul(p.values)).ok_or("weight overflow")?||f.len()!=p.heads*p.rank||e.len()!=f.len()||expected.iter().any(|x|x.len()!=p.heads*p.values){return Err("loaded operand extents".into())}
 let dev=CudaDevice::new_with_stream(0).map_err(|e|e.to_string())?;let mut uuid=unsafe{std::mem::zeroed::<sys::CUuuid>()};unsafe{sys::lib().cuDeviceGetUuid_v2(&mut uuid,*dev.cu_device())}.result().map_err(|e|e.to_string())?;let h=uuid.bytes.iter().map(|b|format!("{:02x}",*b as u8)).collect::<String>();let actual=format!("GPU-{}-{}-{}-{}-{}",&h[..8],&h[8..12],&h[12..16],&h[16..20],&h[20..]);if actual!=p.gpu_uuid{return Err("physical UUID".into())}dev.load_ptx(String::from_utf8(p.native_ptx.read()?).map_err(|e|e.to_string())?.into(),"wvc_native",&["mla_apply_wvc"]).map_err(|e|e.to_string())?;let native=dev.get_func("wvc_native","mla_apply_wvc").ok_or("native WVC absent")?;let dw=dev.htod_sync_copy(&w).map_err(|e|e.to_string())?;let wf:Vec<_>=w.iter().map(|&v|widen(v)).collect();let dwf=dev.htod_sync_copy(&wf).map_err(|e|e.to_string())?;let blas=Blas(br::create_handle().map_err(|e|e.to_string())?);unsafe{br::set_stream(blas.0,*dev.cu_stream()as _)}.map_err(|e|e.to_string())?;let mut lt=lt::Probe::new(dev.clone(),p.rank,2,p.values,1.0,true)?;
 let root=PathBuf::from(out);fs::create_dir(&root).map_err(|e|e.to_string())?;let mut results=Vec::new();
 for (case,input)in [("full",&f),("decode",&e)]{
  let dx=dev.htod_sync_copy(input).map_err(|e|e.to_string())?;let dy=dev.alloc_zeros::<u16>(p.heads*p.values).map_err(|e|e.to_string())?;unsafe{native.clone().launch(LaunchConfig{grid_dim:(p.heads as u32,1,1),block_dim:(256,1,1),shared_mem_bytes:0},(*dy.device_ptr(),*dx.device_ptr(),*dw.device_ptr(),p.heads as i32,p.values as i32,p.rank as i32))}.map_err(|e|e.to_string())?;let nv=dev.dtoh_sync_copy(&dy).map_err(|e|e.to_string())?;if actual==p.source_reference_gpu_uuid&&case=="decode"&&nv!=expected[1]{return Err("native original decode pairing differs".into())}fs::write(root.join(format!("{case}-native.bf16")),bserial(&nv)).map_err(|e|e.to_string())?;
  let mut ref64=Vec::new();for h in 0..p.heads{for v in 0..p.values{let mut sum=0f64;for k in 0..p.rank{sum+=(input[h*p.rank+k]as f64)*(wf[(h*p.values+v)*p.rank+k]as f64);}ref64.push(sum);}}fs::write(root.join(format!("{case}-reference.f64")),ref64.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).map_err(|e|e.to_string())?;
  let mut counts=Vec::new();for &m in &p.tokens{if m==0||m>i32::MAX as usize{return Err("tokens".into())}let len=p.heads.checked_mul(m).and_then(|n|n.checked_mul(p.rank)).ok_or("token operand overflow")?;let mut repeated=Vec::with_capacity(len);for h in 0..p.heads{for _ in 0..m{repeated.extend_from_slice(&input[h*p.rank..(h+1)*p.rank]);}}let b:Vec<_>=repeated.iter().map(|&v|round(v)).collect();let db=dev.htod_sync_copy(&b).map_err(|e|e.to_string())?;let drep=dev.htod_sync_copy(&repeated).map_err(|e|e.to_string())?;let dout=dev.alloc_zeros::<u16>(p.heads*m*p.values).map_err(|e|e.to_string())?;let (one,zero)=(1f32,0f32);unsafe{br::gemm_strided_batched_ex(blas.0,bs::cublasOperation_t::CUBLAS_OP_T,bs::cublasOperation_t::CUBLAS_OP_N,p.values as i32,m as i32,p.rank as i32,&one as *const _ as _,*dw.device_ptr()as _,bs::cudaDataType::CUDA_R_16BF,p.rank as i32,(p.values*p.rank)as i64,*db.device_ptr()as _,bs::cudaDataType::CUDA_R_16BF,p.rank as i32,(m*p.rank)as i64,&zero as *const _ as _,*dout.device_ptr()as _,bs::cudaDataType::CUDA_R_16BF,p.values as i32,(m*p.values)as i64,p.heads as i32,bs::cublasComputeType_t::CUBLAS_COMPUTE_32F,bs::cublasGemmAlgo_t::CUBLAS_GEMM_DEFAULT)}.map_err(|e|e.to_string())?;let bf=dev.dtoh_sync_copy(&dout).map_err(|e|e.to_string())?;fs::write(root.join(format!("{case}-m{m}-bf16.bf16")),bserial(&bf)).map_err(|e|e.to_string())?;
   if actual==p.source_reference_gpu_uuid&&case=="full"&&m==1&&bf!=expected[0]{return Err("original BF16 prefill pairing differs".into())}lt.set_columns(m)?;let ltr=lt.run(*dwf.device_ptr(),*drep.device_ptr(),&vec![0.0;p.heads*m*p.values],p.heads,&root,&format!("{case}-m{m}-wvc"),true,p.profile)?;counts.push(json!({"tokens":m,"lt":ltr,"prefill_original_pairing_exact":case=="full"&&m==1&&bf==expected[0],"source_reference_gpu":p.source_reference_gpu_uuid,"same_gpu_reference":actual==p.source_reference_gpu_uuid}));
  }results.push(json!({"case":case,"shapes":counts}));
 }
 fs::write(root.join("REPORT.json"),serde_json::to_vec_pretty(&json!({"gpu_uuid":actual,"results":results,"plan_sha256":hash(&fs::read(plan).map_err(|e|e.to_string())?),"scope":"Actual F32 inputs and BF16 WVC weights; native/BF16 prefill pairings admitted. Explicit F32 Lt with one-time exact BF16-to-F32 weight copy for diagnostic. Not serving memory/graph/performance/accuracy qualification."})).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;Ok(())
}
fn main(){let v:Vec<_>=std::env::args().collect();if std::env::var("KRASIS_DEV_SCRIPT").as_deref()!=Ok("1")||v.len()!=3{eprintln!("Use ./dev mla-wvc-probe <plan> <new-dir>");std::process::exit(2)}if let Err(e)=run(&v[1],&v[2]){eprintln!("{e}");std::process::exit(1)}}
